'use client';

import * as React from 'react';

// @interlace/live-room v1.4.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/live-room
// What changed since: https://ds.interlace.tools/c/live-room#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — LiveRoom: useRoom and the LiveRoom flow (Lobby, Countdown, HostControls)
 *
 * A game night on one big screen and everyone's phones. The host opens a
 * room and shows its JoinCode; players scan or type it and land in the
 * lobby; the host starts, everyone sees the same countdown, plays the same
 * rounds, and the night ends on a Podium. The rules of the room live in
 * `room-model.ts` (pure), and the network is whatever `RoomTransport` the
 * app passes, so no realtime vendor is built in.
 *
 * ## Flow
 *
 * A flow (docs/philosophies/FLOW_PHILOSOPHY.md): one namespace, `LiveRoom`,
 * and the app holds the room through `useRoom`. Every phase of
 * `RoomPhase`, the part that shows it, and what moves it on:
 *
 * | Phase     | Host screen                                 | Player phone         | Leaves by (event)                        |
 * | --------- | ------------------------------------------- | -------------------- | ---------------------------------------- |
 * | lobby     | LiveRoom.Lobby with JoinCode                | LiveRoom.Lobby       | Start → `countdown`                      |
 * | countdown | LiveRoom.Countdown                          | LiveRoom.Countdown   | its deadline → `question`                |
 * | question  | LiveRoom.HostControls                       | AnswerPad, or Poll   | all answered or the clock → `reveal`     |
 * | reveal    | TallyBars, Standings, LiveRoom.HostControls | AnswerPad (revealed) | Next → `countdown`, or Podium → `podium` |
 * | podium    | Podium, LiveRoom.HostControls               | Podium               | Play again → `restart`, or End → `close` |
 * | closed    | the app's own end screen                    | the app's own screen | —                                        |
 *
 * AnswerPad, Poll, TallyBars, Standings and Podium are game components in their
 * own right, so the flow names them rather than wrapping them. The round's
 * prompt reaches the phones in `room.prompt` and its answer in
 * `room.solution` (see room-model), so AnswerPad never needs the answer early.
 *
 * ## Anatomy
 *
 *   useRoom({ transport, selfId, host? })  → { room, isHost, send }
 *
 *   LiveRoom.Lobby                 (section — data-slot="room-lobby", data-count)
 *     ├─ div                       (data-slot="room-lobby-join": your JoinCode, when given)
 *     ├─ h2                        (data-slot="room-lobby-count": "8 players")
 *     ├─ ul                        (data-slot="room-lobby-players")
 *     │   └─ li × n                (data-slot="room-lobby-player", data-self, data-away)
 *     │       └─ Button?           (data-slot="room-lobby-remove", host only)
 *     ├─ p                         (data-slot="room-lobby-empty", before anyone joins)
 *     ├─ div                       (data-slot="room-lobby-actions": host controls, or "Waiting for the host")
 *     └─ span aria-live            (data-slot="room-lobby-announce": "Dana joined")
 *
 *   LiveRoom.Countdown             (div role="timer" — data-slot="room-countdown", data-state)
 *     ├─ span                      (data-slot="room-countdown-value": 3, 2, 1, then "Go")
 *     └─ span aria-live            (data-slot="room-countdown-announce")
 *
 *   LiveRoom.HostControls          (div role="group" — data-slot="room-host-controls", data-phase)
 *     ├─ p aria-live               (data-slot="room-host-status": "5 of 8 answered")
 *     ├─ Button                    (data-slot="room-host-primary": Start / Reveal / Next / Podium / Play again)
 *     ├─ Button                    (data-slot="room-host-lock": lock or unlock)
 *     └─ Button                    (data-slot="room-host-end")
 *
 * ## Who decides
 *
 * The host's `useRoom` holds the room. A player's `send` travels as an
 * intent; the host applies it only if the model allows it (no joining a
 * locked room, one answer a round, only the host starts) and sends the new
 * state to everyone, with `seq` so an old message never overwrites a new
 * one. A refused intent comes back to that player through `onRejected`.
 *
 * ## Time
 *
 * Deadlines are timestamps from the host's clock. Every state the host sends
 * carries its clock (`at`), and `useRoom` returns `now`: this device's clock
 * corrected to the host's. Pass it to `LiveRoom.Countdown`, `TimerRing` and
 * `useSecondsLeft`, and a phone whose clock is a minute off still shows the
 * host's deadline. Timing uses `setTimeout` to the next whole second, never
 * a frame loop.
 *
 * ## Delivery
 *
 * Networks drop messages. A player's join or answer is sent again every 3s
 * until the host's state shows it (5 tries at most); the host applies it
 * once, and a repeated or late answer gets no reply, since a reply would go
 * to every phone. The host's last state is the truth: a transport may send
 * it again when quiet so a phone that missed one catches up.
 *
 * ## Presence
 *
 * A player's page says it is away on `pagehide` and asks for the room again
 * when it is seen (a phone that slept missed messages). Shown away while
 * still here, it rejoins by itself under the same id and name, scores kept;
 * a player who sends `leave` stays out. Turn it off with `presence: false`.
 *
 * ## Motion
 *
 * A player's chip pops in when they join (scale only, 240ms);
 * each countdown number lands with a short scale (400ms). Under reduced
 * motion both are simply there. The words carry everything: joins and the
 * countdown are announced, sparsely.
 *
 * ## MIN_VIEWPORT — 320
 *
 * | Rule | Concept                   | Where in this file                                   |
 * | ---- | ------------------------- | ---------------------------------------------------- |
 * | R4   | Extends native el         | `section` / `div` props                              |
 * | R6   | data-slot per part        | room-lobby-*, room-countdown-*, room-host-*          |
 * | R7   | cn + ...rest              | `cn(…, className)` + `{...props}`                    |
 * | R8   | Enums, not booleans       | `size`                                               |
 * | R14  | Declares min viewport     | `data-min-viewport` + exported const                 |
 * | R25  | Client component          | the room runs in the browser                         |
 * | R26  | A11y                      | list of players; sparse live announcements; timer role |
 */

import { Lock, LockOpen, X } from 'lucide-react';

import { cn } from '@/lib/utils';
import { useReducedMotion } from '@/hooks/use-reduced-motion';
import { Button } from '@/components/ui/button';
import {
  answerProgress,
  applyRoomEvent,
  clockOffset,
  connectedPlayers,
  rejectRoomEvent,
  type RoomEvent,
  type RoomHostEvent,
  type RoomPlayer,
  type RoomRejection,
  type RoomSettings,
  type RoomState,
  type RoomTransport,
} from '@/components/ui/games/room-model';

export const MIN_VIEWPORT = 320 as const;

const EASE = 'cubic-bezier(0.16, 1, 0.3, 1)';

// --- useRoom --------------------------------------------------------------------

export interface UseRoomOptions {
  /** How messages travel. null while connecting. */
  transport: RoomTransport | null;
  /** This client's id: the host's id for the host, the player's id for a player. */
  selfId: string;
  /** The room to start from, on the host only. Present = this client is the host. */
  host?: RoomState;
  /** A player only: accept states for this room code only. */
  code?: string;
  settings?: RoomSettings;
  /** A player's intent (or the host's own event) was refused. */
  onRejected?: (reason: RoomRejection, event: RoomEvent['type']) => void;
  /** The host's clock, which stamps each answer and join as it arrives. @default Date.now */
  now?: () => number;
  /**
   * A player only: say "away" when the page is closed or hidden for good (`pagehide`), and come
   * back by itself when the page is seen again or the host shows this player away. A player who
   * sends `leave` themselves stays out. @default true
   */
  presence?: boolean;
}

export interface UseRoomResult {
  /** The room as this client knows it. null on a player until the host answers. */
  room: RoomState | null;
  isHost: boolean;
  /** Apply (host) or ask the host to apply (player). */
  send: (event: RoomEvent) => void;
  /**
   * This client's clock, corrected to the host's: pass it as `now` to `LiveRoom.Countdown`,
   * `TimerRing` and `useSecondsLeft`, so every phone shows the host's deadline, whatever its own
   * clock says. On the host it is `now`.
   */
  now: () => number;
}

const OFFSET_WINDOW_MS = 60_000;
const REJOIN_EVERY_MS = 3_000;
/** A player's join or answer is sent again this often until the host's state shows it. */
const RESEND_EVERY_MS = 3_000;
const RESEND_TRIES = 5;

/** True once `state` shows the player's `event` (or it can no longer count). */
function settled(state: RoomState, event: RoomEvent, round: number): boolean {
  if (event.type === 'join') return state.players.some((p) => p.id === event.playerId && p.connected);
  if (event.type === 'answer')
    return state.phase !== 'question' || state.round !== round || event.playerId in state.answers;
  return true;
}

export function useRoom({
  transport,
  selfId,
  host,
  code,
  settings,
  onRejected,
  now = Date.now,
  presence = true,
}: UseRoomOptions): UseRoomResult {
  const isHost = host !== undefined;
  const [room, setRoom] = React.useState<RoomState | null>(host ?? null);
  const roomRef = React.useRef<RoomState | null>(host ?? null);
  const latest = React.useRef({ settings, onRejected, code, now });
  latest.current = { settings, onRejected, code, now };
  // A player's measure of the host's clock: recent (host send, local receive) pairs.
  const samples = React.useRef<{ at: number; local: number }[]>([]);
  const offset = React.useRef(0);
  const leftOnPurpose = React.useRef(false);
  const lastRejoin = React.useRef(-Infinity);
  // A player's join or answer, until the host's state shows it: networks drop messages.
  const pending = React.useRef<{ event: RoomEvent; round: number; tries: number } | null>(null);
  const [pendingTick, setPendingTick] = React.useState(0);

  const apply = React.useCallback(
    (event: RoomEvent, from: string) => {
      const current = roomRef.current;
      if (!current) return;
      const reason = rejectRoomEvent(current, event, from, latest.current.settings);
      if (reason) {
        if (from === selfId) latest.current.onRejected?.(reason, event.type);
        // A refused answer (a repeat, or one that arrived after the reveal) gets no reply: it
        // would go to every phone, and the state already tells the player what counted.
        else if (event.type !== 'answer')
          transport?.send({
            kind: 'rejected',
            to: from,
            event: event.type,
            reason,
          });
        return;
      }
      const next = applyRoomEvent(current, event, from, latest.current.settings);
      roomRef.current = next;
      setRoom(next);
      transport?.send({ kind: 'state', state: next, at: latest.current.now() });
    },
    [transport, selfId],
  );

  React.useEffect(() => {
    if (!transport) return;
    const off = transport.subscribe((message) => {
      if (isHost) {
        if (message.kind === 'intent') {
          // The host's clock decides when an answer or a join arrived, never the sender's.
          const event = message.event;
          apply(
            event.type === 'answer' || event.type === 'join' ? { ...event, at: latest.current.now() } : event,
            message.from,
          );
        } else if (message.kind === 'hello' && roomRef.current)
          transport.send({ kind: 'state', state: roomRef.current, at: latest.current.now() });
        return;
      }
      if (message.kind === 'state') {
        const current = roomRef.current;
        const want = latest.current.code;
        if (want && message.state.code !== want) return;
        if (typeof message.at === 'number') {
          const local = Date.now();
          samples.current = [
            ...samples.current.filter((s) => local - s.local < OFFSET_WINDOW_MS),
            { at: message.at, local },
          ];
          offset.current = clockOffset(samples.current);
        }
        // Shown away (the phone slept, or its leave crossed a reload): come back, unless we left.
        const self = message.state.players.find((p) => p.id === selfId);
        if (
          presence &&
          self &&
          !self.connected &&
          !leftOnPurpose.current &&
          message.state.phase !== 'closed' &&
          !message.state.removed.includes(selfId) &&
          (typeof document === 'undefined' || document.visibilityState !== 'hidden') &&
          Date.now() - lastRejoin.current > REJOIN_EVERY_MS
        ) {
          lastRejoin.current = Date.now();
          transport.send({ kind: 'intent', from: selfId, event: { type: 'join', playerId: selfId, name: self.name } });
        }
        if (current && current.code === message.state.code && message.state.seq <= current.seq) return;
        roomRef.current = message.state;
        setRoom(message.state);
        const wait = pending.current;
        if (wait && settled(message.state, wait.event, wait.round)) pending.current = null;
      } else if (message.kind === 'rejected' && message.to === selfId) {
        if (pending.current?.event.type === message.event) pending.current = null;
        latest.current.onRejected?.(message.reason, message.event);
      }
    });
    if (isHost) {
      if (roomRef.current) transport.send({ kind: 'state', state: roomRef.current, at: latest.current.now() });
    } else {
      transport.send({ kind: 'hello', from: selfId });
    }
    return off;
  }, [transport, isHost, selfId, apply, presence]);

  // A player's page: away when it is closed, and a fresh look at the room when it is seen again
  // (a phone that slept missed messages; the answer may bring it back in, see above).
  React.useEffect(() => {
    if (isHost || !presence || !transport || typeof window === 'undefined') return;
    const hide = (e: PageTransitionEvent) => {
      // A page kept for back/forward is not gone; a closed one is.
      if (e.persisted) return;
      if (roomRef.current?.players.some((p) => p.id === selfId && p.connected))
        transport.send({ kind: 'intent', from: selfId, event: { type: 'leave', playerId: selfId } });
    };
    const seen = () => {
      if (document.visibilityState === 'visible') transport.send({ kind: 'hello', from: selfId });
    };
    window.addEventListener('pagehide', hide);
    document.addEventListener('visibilitychange', seen);
    return () => {
      window.removeEventListener('pagehide', hide);
      document.removeEventListener('visibilitychange', seen);
    };
  }, [isHost, presence, transport, selfId]);

  const send = React.useCallback(
    (event: RoomEvent) => {
      if (isHost) apply(event, selfId);
      else {
        if (event.type === 'leave') leftOnPurpose.current = true;
        else if (event.type === 'join') leftOnPurpose.current = false;
        if (event.type === 'join' || event.type === 'answer') {
          pending.current = { event, round: roomRef.current?.round ?? 0, tries: 0 };
          setPendingTick((n) => n + 1);
        }
        transport?.send({ kind: 'intent', from: selfId, event });
      }
    },
    [isHost, apply, selfId, transport],
  );

  // Send a waiting join or answer again until the host's state shows it, a few times at most.
  React.useEffect(() => {
    if (isHost || !transport) return;
    const timer = setInterval(() => {
      const wait = pending.current;
      if (!wait) return clearInterval(timer);
      const current = roomRef.current;
      if (current && settled(current, wait.event, wait.round)) {
        pending.current = null;
        return clearInterval(timer);
      }
      if (wait.tries >= RESEND_TRIES) {
        pending.current = null;
        return clearInterval(timer);
      }
      wait.tries++;
      transport.send({ kind: 'intent', from: selfId, event: wait.event });
    }, RESEND_EVERY_MS);
    return () => clearInterval(timer);
  }, [isHost, transport, selfId, pendingTick]);

  const corrected = React.useCallback(() => (isHost ? latest.current.now() : Date.now() + offset.current), [isHost]);

  return { room, isHost, send, now: corrected };
}

/**
 * Whole seconds until `target` (a timestamp in ms), re-rendering at each
 * second boundary with `setTimeout`. null when there is no target.
 */
export function useSecondsLeft(target: number | null, now: () => number = Date.now): number | null {
  const [, tick] = React.useReducer((n: number) => n + 1, 0);
  const left = target === null ? null : Math.max(0, Math.ceil((target - now()) / 1000));
  React.useEffect(() => {
    if (target === null) return;
    const ms = target - now();
    if (ms <= 0) return;
    const t = setTimeout(tick, ms % 1000 || 1000);
    return () => clearTimeout(t);
  });
  return left;
}

// --- LiveRoomLobby ------------------------------------------------------------------

export interface LiveRoomLobbyLabels {
  /** The heading. @default (n) => n === 1 ? '1 player' : `${n} players` */
  count?: (n: number) => string;
  /** @default 'Waiting for players to join.' */
  empty?: string;
  /** On the viewer's own chip. @default 'You' */
  you?: string;
  /** On a player who dropped out. @default 'away' */
  away?: string;
  /** @default (name) => `Remove ${name}` */
  remove?: (name: string) => string;
  /** @default (names) => names.length === 1 ? `${names[0]} joined` : `${names.length} players joined` */
  joined?: (names: string[]) => string;
  /** A player's view, where the host controls would be. @default 'You are in. Waiting for the host to start.' */
  waiting?: string;
  /** Names the player list. @default 'Players' */
  list?: string;
}

/**
 * The lobby is a landmark named by its player count. With more than one lobby
 * on a page (a host screen beside a preview), give each its own `aria-label`,
 * which then names the landmark instead.
 */
type LiveRoomLobbyProps = Omit<React.ComponentProps<'section'>, 'children'> & {
  players: readonly RoomPlayer[];
  /** The viewer's id, to mark their chip. */
  selfId?: string;
  /** Your JoinCode (or any way in), shown beside the players. */
  join?: React.ReactNode;
  /** Host controls. Leave out on a player's screen to show `labels.waiting`. */
  actions?: React.ReactNode;
  /** Shows a remove button on each chip (host only). */
  onRemove?: (playerId: string) => void;
  /** Hide players who dropped out. @default false */
  hideAway?: boolean;
  labels?: LiveRoomLobbyLabels;
};

const COUNT = (n: number) => (n === 1 ? '1 player' : `${n} players`);
const JOINED = (names: string[]) => (names.length === 1 ? `${names[0]} joined` : `${names.length} players joined`);

function LiveRoomLobby({
  players,
  selfId,
  join,
  actions,
  onRemove,
  hideAway = false,
  labels,
  className,
  ...props
}: LiveRoomLobbyProps) {
  const reduced = useReducedMotion();
  const listRef = React.useRef<HTMLUListElement>(null);
  const seen = React.useRef<Set<string> | null>(null);
  const [announce, setAnnounce] = React.useState('');
  const shown = hideAway ? players.filter((p) => p.connected) : players;
  const live = players.filter((p) => p.connected).length;
  const headingId = React.useId();

  React.useEffect(() => {
    const ids = new Set(players.map((p) => p.id));
    const before = seen.current;
    seen.current = ids;
    if (!before) return; // first render: no entrance, no announcement
    const fresh = players.filter((p) => !before.has(p.id));
    if (!fresh.length) return;
    setAnnounce((labels?.joined ?? JOINED)(fresh.map((p) => p.name)));
    if (reduced) return;
    const freshIds = new Set(fresh.map((p) => p.id));
    const chips = listRef.current?.querySelectorAll<HTMLElement>('[data-player-id]') ?? [];
    for (const el of chips) {
      if (!freshIds.has(el.dataset.playerId ?? '')) continue;
      if (typeof el.animate === 'function') {
        el.animate(
          // Scale only: a fading name would dip below text contrast mid-entrance.
          [{ transform: 'scale(0.6)' }, { transform: 'scale(1)' }],
          { duration: 240, easing: EASE },
        );
      }
    }
  }, [players, reduced, labels]);

  return (
    <section
      data-slot="room-lobby"
      data-count={live}
      data-min-viewport={String(MIN_VIEWPORT)}
      aria-labelledby={props['aria-label'] ? undefined : headingId}
      className={cn('@container', className)}
      {...props}
    >
      <div className={cn('grid gap-8', join && '@3xl:grid-cols-[2fr_3fr] @3xl:items-start')}>
        {join ? <div data-slot="room-lobby-join">{join}</div> : null}
        <div className="flex min-w-0 flex-col gap-4">
          <h2 id={headingId} data-slot="room-lobby-count" className="text-2xl font-semibold tabular-nums">
            {(labels?.count ?? COUNT)(live)}
          </h2>
          {shown.length ? (
            <ul
              ref={listRef}
              data-slot="room-lobby-players"
              aria-label={labels?.list ?? 'Players'}
              className="flex flex-wrap gap-2"
            >
              {shown.map((p) => {
                const self = p.id === selfId;
                return (
                  <li
                    key={p.id}
                    data-slot="room-lobby-player"
                    data-player-id={p.id}
                    data-self={self ? '' : undefined}
                    data-away={p.connected ? undefined : ''}
                    className={cn(
                      'bg-card text-card-foreground inline-flex max-w-full min-w-0 items-center gap-1.5 rounded-full border py-1.5 ps-3.5 text-sm font-medium',
                      onRemove ? 'pe-1' : 'pe-3.5',
                      self ? 'border-primary' : 'border-border',
                      !p.connected && 'text-muted-foreground border-dashed',
                    )}
                  >
                    <span className="truncate">{p.name}</span>
                    {self ? (
                      <span className="text-primary shrink-0 text-xs font-semibold">{labels?.you ?? 'You'}</span>
                    ) : null}
                    {!p.connected ? <span className="shrink-0 text-xs">{labels?.away ?? 'away'}</span> : null}
                    {onRemove && !self ? (
                      <Button
                        data-slot="room-lobby-remove"
                        type="button"
                        variant="ghost"
                        size="icon-xs"
                        className="rounded-full"
                        aria-label={(labels?.remove ?? ((n: string) => `Remove ${n}`))(p.name)}
                        onClick={() => onRemove(p.id)}
                      >
                        <X aria-hidden />
                      </Button>
                    ) : null}
                  </li>
                );
              })}
            </ul>
          ) : (
            <p data-slot="room-lobby-empty" className="text-muted-foreground">
              {labels?.empty ?? 'Waiting for players to join.'}
            </p>
          )}
          <div data-slot="room-lobby-actions" className="pt-2">
            {actions ?? (
              <p className="text-muted-foreground">{labels?.waiting ?? 'You are in. Waiting for the host to start.'}</p>
            )}
          </div>
        </div>
      </div>
      <span data-slot="room-lobby-announce" aria-live="polite" className="sr-only">
        {announce}
      </span>
    </section>
  );
}
LiveRoomLobby.displayName = 'LiveRoom.Lobby';

// --- LiveRoomCountdown --------------------------------------------------------------

export interface LiveRoomCountdownLabels {
  /** Names the timer. @default 'Starting in' */
  name?: string;
  /** Spoken once, when the countdown appears. @default (s) => `Starting in ${s} seconds` */
  starting?: (seconds: number) => string;
  /** Shown and spoken at 0. @default 'Go' */
  go?: string;
}

type LiveRoomCountdownProps = Omit<React.ComponentProps<'div'>, 'children'> & {
  /** When it reaches 0, in ms (host clock). null: idle. */
  startsAt: number | null;
  /** Your clock, corrected to the host's. @default Date.now */
  now?: () => number;
  /** Called once at 0. */
  onDone?: () => void;
  /** @default 'default' */
  size?: 'default' | 'stage';
  labels?: LiveRoomCountdownLabels;
};

const COUNTDOWN_SIZE = {
  default: 'size-28 text-5xl',
  stage: 'size-44 text-7xl',
} as const;

function LiveRoomCountdown({
  startsAt,
  now = Date.now,
  onDone,
  size = 'default',
  labels,
  className,
  ...props
}: LiveRoomCountdownProps) {
  const reduced = useReducedMotion();
  const left = useSecondsLeft(startsAt, now);
  const valueRef = React.useRef<HTMLSpanElement>(null);
  const done = left === 0;
  const fired = React.useRef<number | null>(null);
  const [announce, setAnnounce] = React.useState('');
  const go = labels?.go ?? 'Go';
  const latest = React.useRef(onDone);
  latest.current = onDone;

  // Speak once on arrival and once at 0, never every second. The deps are
  // `startsAt` alone on purpose: a new `now` or `labels` must not re-announce
  // mid-countdown.
  React.useEffect(() => {
    if (startsAt === null) return;
    const s = Math.max(0, Math.ceil((startsAt - now()) / 1000));
    if (s > 0) setAnnounce((labels?.starting ?? ((n: number) => `Starting in ${n} seconds`))(s));
  }, [startsAt]);

  React.useEffect(() => {
    if (!done || startsAt === null || fired.current === startsAt) return;
    fired.current = startsAt;
    setAnnounce(go);
    latest.current?.();
  }, [done, startsAt, go]);

  React.useEffect(() => {
    if (left === null || reduced) return;
    const el = valueRef.current;
    if (!el || typeof el.animate !== 'function') return;
    el.animate(
      // Scale only, like the chips: a fading number would dip below text contrast.
      [{ transform: 'scale(1.5)' }, { transform: 'scale(1)' }],
      { duration: 400, easing: EASE },
    );
  }, [left, reduced]);

  return (
    <div
      role="timer"
      aria-label={labels?.name ?? 'Starting in'}
      data-slot="room-countdown"
      data-state={startsAt === null ? 'idle' : done ? 'done' : 'running'}
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn(
        'border-primary text-foreground grid place-items-center rounded-full border-4 font-semibold tabular-nums',
        done && 'bg-primary text-primary-foreground',
        COUNTDOWN_SIZE[size],
        className,
      )}
      {...props}
    >
      <span ref={valueRef} data-slot="room-countdown-value" className={cn('leading-none', done && 'text-[0.6em]')}>
        {left === null ? '' : done ? go : left}
      </span>
      <span data-slot="room-countdown-announce" aria-live="assertive" className="sr-only">
        {announce}
      </span>
    </div>
  );
}
LiveRoomCountdown.displayName = 'LiveRoom.Countdown';

// --- LiveRoomHostControls -----------------------------------------------------------

export interface LiveRoomHostControlsLabels {
  /** @default 'Host controls' */
  group?: string;
  /** @default 'Start' */
  start?: string;
  /** @default (min, n) => `Needs ${min} players to start. ${n} so far.` */
  needMore?: (min: number, players: number) => string;
  /** @default (n) => n === 1 ? '1 player is in.' : `${n} players are in.` */
  ready?: (players: number) => string;
  /** @default 'Starting…' */
  starting?: string;
  /** @default (a, t) => `${a} of ${t} answered` */
  answered?: (answered: number, total: number) => string;
  /** @default 'Reveal now' */
  reveal?: string;
  /** @default (round, rounds) => rounds ? `Round ${round} of ${rounds}` : `Round ${round}` */
  round?: (round: number, rounds: number | null) => string;
  /** @default 'Next round' */
  next?: string;
  /** @default 'Show the podium' */
  podium?: string;
  /** @default 'Play again' */
  restart?: string;
  /** @default 'Lock the room' */
  lock?: string;
  /** @default 'Unlock the room' */
  unlock?: string;
  /** @default 'End the game' */
  end?: string;
  /** @default 'The game has ended.' */
  closed?: string;
}

type LiveRoomHostControlsProps = Omit<React.ComponentProps<'div'>, 'children'> & {
  room: RoomState;
  /** `send` from the host's `useRoom`. */
  send: (event: RoomHostEvent) => void;
  /** Players needed to start. @default 1 */
  minPlayers?: number;
  /** Seconds of countdown before each round. @default 3 */
  countdownSeconds?: number;
  /** Seconds per round, or null for no clock. @default 20 */
  roundSeconds?: number | null;
  /** Points per player id for the round being revealed. @default () => ({}) */
  score?: (room: RoomState) => Record<string, number>;
  /**
   * Move on by itself: open the round when the countdown ends, reveal when
   * the clock runs out or everyone has answered. @default true
   */
  autoAdvance?: boolean;
  /** @default Date.now */
  now?: () => number;
  labels?: LiveRoomHostControlsLabels;
};

const NO_POINTS = () => ({});

function LiveRoomHostControls({
  room,
  send,
  minPlayers = 1,
  countdownSeconds = 3,
  roundSeconds = 20,
  score = NO_POINTS,
  autoAdvance = true,
  now = Date.now,
  labels,
  className,
  ...props
}: LiveRoomHostControlsProps) {
  const L = labels ?? {};
  const live = connectedPlayers(room).length;
  const { answered, total } = answerProgress(room);
  const latest = React.useRef({ send, score, now, roundSeconds });
  latest.current = { send, score, now, roundSeconds };

  const openRound = React.useCallback(() => {
    const { send: s, now: n, roundSeconds: r } = latest.current;
    s({ type: 'question', endsAt: r === null ? null : n() + r * 1000 });
  }, []);
  const reveal = React.useCallback(() => {
    latest.current.send({ type: 'reveal', points: latest.current.score(room) });
  }, [room]);

  // Countdown over → open the round. Clock out or all in → reveal.
  React.useEffect(() => {
    if (!autoAdvance) return;
    const n = latest.current.now;
    if (room.phase === 'countdown' && room.startsAt !== null) {
      const t = setTimeout(openRound, Math.max(0, room.startsAt - n()));
      return () => clearTimeout(t);
    }
    if (room.phase === 'question') {
      if (total > 0 && answered >= total) {
        const t = setTimeout(reveal, 600);
        return () => clearTimeout(t);
      }
      if (room.endsAt !== null) {
        const t = setTimeout(reveal, Math.max(0, room.endsAt - n()));
        return () => clearTimeout(t);
      }
    }
    return undefined;
  }, [autoAdvance, room.phase, room.startsAt, room.endsAt, answered, total, openRound, reveal]);

  const countdown = () => send({ type: 'countdown', startsAt: now() + countdownSeconds * 1000 });
  const last = room.rounds !== null && room.round >= room.rounds;

  let status: string;
  let primary: {
    label: string;
    onClick: () => void;
    disabled?: boolean;
  } | null = null;
  switch (room.phase) {
    case 'lobby':
      status =
        live < minPlayers
          ? (L.needMore ?? ((m: number, n: number) => `Needs ${m} players to start. ${n} so far.`))(minPlayers, live)
          : (L.ready ?? ((n: number) => (n === 1 ? '1 player is in.' : `${n} players are in.`)))(live);
      primary = {
        label: L.start ?? 'Start',
        onClick: countdown,
        disabled: live < minPlayers,
      };
      break;
    case 'countdown':
      status = L.starting ?? 'Starting…';
      break;
    case 'question':
      status = (L.answered ?? ((a: number, t: number) => `${a} of ${t} answered`))(answered, total);
      primary = { label: L.reveal ?? 'Reveal now', onClick: reveal };
      break;
    case 'reveal':
      status = (L.round ?? ((r: number, rs: number | null) => (rs ? `Round ${r} of ${rs}` : `Round ${r}`)))(
        room.round,
        room.rounds,
      );
      primary = last
        ? {
            label: L.podium ?? 'Show the podium',
            onClick: () => send({ type: 'podium' }),
          }
        : { label: L.next ?? 'Next round', onClick: countdown };
      break;
    case 'podium':
      status = (L.round ?? ((r: number, rs: number | null) => (rs ? `Round ${r} of ${rs}` : `Round ${r}`)))(
        room.round,
        room.rounds,
      );
      primary = {
        label: L.restart ?? 'Play again',
        onClick: () => send({ type: 'restart' }),
      };
      break;
    default:
      status = L.closed ?? 'The game has ended.';
  }

  return (
    <div
      role="group"
      aria-label={L.group ?? 'Host controls'}
      data-slot="room-host-controls"
      data-phase={room.phase}
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('flex flex-wrap items-center gap-3', className)}
      {...props}
    >
      <p
        data-slot="room-host-status"
        aria-live="polite"
        className="text-muted-foreground basis-full text-sm tabular-nums"
      >
        {status}
      </p>
      {primary ? (
        <Button
          data-slot="room-host-primary"
          type="button"
          size="lg"
          disabled={primary.disabled}
          onClick={primary.onClick}
        >
          {primary.label}
        </Button>
      ) : null}
      {room.phase !== 'closed' ? (
        <>
          <Button
            data-slot="room-host-lock"
            type="button"
            variant="outline"
            onClick={() => send({ type: 'lock', locked: !room.locked })}
          >
            {room.locked ? <Lock aria-hidden /> : <LockOpen aria-hidden />}
            {room.locked ? (L.unlock ?? 'Unlock the room') : (L.lock ?? 'Lock the room')}
          </Button>
          <Button data-slot="room-host-end" type="button" variant="ghost" onClick={() => send({ type: 'close' })}>
            {L.end ?? 'End the game'}
          </Button>
        </>
      ) : null}
    </div>
  );
}
LiveRoomHostControls.displayName = 'LiveRoom.HostControls';

/**
 * The live room flow. One import; every part is `LiveRoom.<Part>`, named for
 * what it is on the screen. The hook, the labels and the props stay flat.
 */
const LiveRoom = {
  Lobby: LiveRoomLobby,
  Countdown: LiveRoomCountdown,
  HostControls: LiveRoomHostControls,
} as const;

export { LiveRoom };
export type { LiveRoomLobbyProps, LiveRoomCountdownProps, LiveRoomHostControlsProps };

export interface LeaderboardEntry {
  /** Stable id: a player or a group. */
  id: string;
  /** What the board shows. */
  name: string;
  score: number;
  /** Breaks ties on score: lower first (time taken, say). Equal or missing values share a rank. */
  tiebreak?: number;
}

export interface RankedEntry extends LeaderboardEntry {
  /** 1-based; ties share a rank and the next rank skips (1, 2, 2, 4). */
  rank: number;
  /** True when another entry has the same rank. */
  tied: boolean;
}

export interface RankOptions {
  /** `desc` when a higher score wins. @default 'desc' */
  order?: 'desc' | 'asc';
  /** Below this many entries the board is hidden. @default 1 */
  minPlayers?: number;
  /** Rows to show from the top. @default all */
  limit?: number;
  /** The viewing player's id: their row is kept even outside `limit`. */
  currentId?: string;
}

export interface RankedBoard {
  /** False while fewer than `minPlayers` have played. */
  visible: boolean;
  /** Entries counted. */
  players: number;
  /** The top rows, within `limit`. Empty while hidden. */
  top: RankedEntry[];
  /** The viewing player's row when it falls outside `top`. */
  current?: RankedEntry;
}

/** Rank every entry. */
export function rankEntries(entries: readonly LeaderboardEntry[], order: 'desc' | 'asc' = 'desc'): RankedEntry[] {
  const sign = order === 'desc' ? -1 : 1;
  const sorted = entries
    .slice()
    .sort(
      (a, b) =>
        sign * (a.score - b.score) || (a.tiebreak ?? Infinity) - (b.tiebreak ?? Infinity) || a.name.localeCompare(b.name),
    );
  const same = (a: LeaderboardEntry, b: LeaderboardEntry) => a.score === b.score && (a.tiebreak ?? null) === (b.tiebreak ?? null);
  const ranked: RankedEntry[] = [];
  sorted.forEach((entry, i) => {
    const prev = sorted[i - 1];
    const rank = prev && same(prev, entry) ? (ranked[i - 1] as RankedEntry).rank : i + 1;
    ranked.push({ ...entry, rank, tied: false });
  });
  for (let i = 0; i < ranked.length; i++) {
    const r = ranked[i] as RankedEntry;
    r.tied = ranked[i - 1]?.rank === r.rank || ranked[i + 1]?.rank === r.rank;
  }
  return ranked;
}

/** The board as a page shows it: hidden below the minimum, top rows, and the viewer's own row. */
export function buildBoard(entries: readonly LeaderboardEntry[], options: RankOptions = {}): RankedBoard {
  const { order = 'desc', minPlayers = 1, limit, currentId } = options;
  const players = entries.length;
  if (players < Math.max(1, minPlayers)) return { visible: false, players, top: [] };
  const ranked = rankEntries(entries, order);
  const top = limit === undefined ? ranked : ranked.slice(0, limit);
  const mine = currentId === undefined ? undefined : ranked.find((e) => e.id === currentId);
  const current = mine && !top.includes(mine) ? mine : undefined;
  return { visible: true, players, top, current };
}

/**
 * @interlace/ui — games/leaderboard-model
 *
 * Ranking for a group's board: ties share a rank (1, 2, 2, 4), the board
 * stays hidden until enough people have played, and the player's own row is
 * found even when it falls outside the top rows. Pure, so the server that
 * stores scores ranks them the same way.
 *
 * ## Why a minimum
 *
 * A board of two people tells each of them exactly what the other scored.
 * `minPlayers` keeps a small group's scores private until there are enough
 * of them to stand in a crowd.
 */

import { rankEntries, type RankedEntry } from '@/components/ui/games/leaderboard-model';

/**
 * @interlace/ui — games/room-model
 *
 * The pure core of a live room: one host on a big screen, players on their
 * phones, a join code, a lobby, rounds and a podium. Every client runs the
 * same reducer, so the host's screen and every phone agree on what happens,
 * and a server can replay a room from its events.
 *
 * The host is the authority. Players send intents (join, leave, answer); the
 * host applies them with `applyRoomEvent`, which refuses anything the sender
 * may not do, and sends the new state to everyone. How messages travel is a
 * `RoomTransport`: two functions, so any realtime service fits behind it. The
 * kit ships an in-memory hub (tests, demos, one screen) and a
 * BroadcastChannel transport (tabs on one device); a WebSocket or hosted
 * realtime adapter is a few lines in the app.
 *
 * Time is always a timestamp in ms from the host's clock (`startsAt`,
 * `endsAt`), so a phone that joins late counts down to the same moment.
 */

// --- Join codes -----------------------------------------------------------------

/** Letters and digits no one misreads: no 0/O, 1/I/L, or U/V. */
export const JOIN_CODE_ALPHABET = '23456789ABCDEFGHJKMNPQRSTWXYZ';

export interface JoinCodeOptions {
  /** @default 6 */
  length?: number;
  /** @default JOIN_CODE_ALPHABET. Pass '0123456789' for a numeric PIN. */
  alphabet?: string;
}

/**
 * A new join code. Leave `random` out to draw from `crypto.getRandomValues`
 * without bias (rejection sampling on a bit mask); pass a function returning
 * a float in [0, 1) for seeded tests. The alphabet holds at most 256 characters.
 */
export function makeJoinCode(options: JoinCodeOptions = {}, random?: () => number): string {
  const { length = 6, alphabet = JOIN_CODE_ALPHABET } = options;
  const n = alphabet.length;
  if (n < 1 || n > 256) throw new RangeError('A join code alphabet holds 1 to 256 characters.');
  const crypto = (globalThis as { crypto?: Crypto }).crypto;
  let code = '';
  if (!random && crypto?.getRandomValues) {
    const mask = 2 ** Math.ceil(Math.log2(n)) - 1;
    while (code.length < length) {
      for (const byte of crypto.getRandomValues(new Uint8Array(length * 2))) {
        const index = byte & mask;
        if (index < n && code.length < length) code += alphabet[index];
      }
    }
    return code;
  }
  const pick = random ?? Math.random;
  for (let i = 0; i < length; i++) code += alphabet[Math.min(n - 1, Math.floor(pick() * n))];
  return code;
}

/**
 * What someone typed, as a code: upper case, spaces and dashes dropped.
 * Returns null when it has the wrong length or a character outside the
 * alphabet, so the field can say so before anything is sent.
 */
export function normalizeJoinCode(input: string, options: JoinCodeOptions = {}): string | null {
  const { length = 6, alphabet = JOIN_CODE_ALPHABET } = options;
  const code = input.toUpperCase().replace(/[\s\-–—.]/g, '');
  if (code.length !== length) return null;
  for (const ch of code) if (!alphabet.includes(ch)) return null;
  return code;
}

/** A code in groups for reading aloud and on a big screen: "K7Q 4MZ". */
export function formatJoinCode(code: string, group = 3): string {
  if (group <= 0) return code;
  const parts: string[] = [];
  for (let i = 0; i < code.length; i += group) parts.push(code.slice(i, i + group));
  return parts.join(' ');
}

// --- State ----------------------------------------------------------------------

export type RoomPhase = 'lobby' | 'countdown' | 'question' | 'reveal' | 'podium' | 'closed';

export interface RoomPlayer {
  id: string;
  name: string;
  /** False after `leave`; the player keeps their score and can come back. */
  connected: boolean;
}

export interface RoomState {
  code: string;
  hostId: string;
  phase: RoomPhase;
  /** No new players while locked. Players already in can still reconnect. */
  locked: boolean;
  /**
   * When the join code stops letting new players in, in ms (host clock), or
   * null for a code that lasts as long as the room. Players already in can
   * still reconnect after it.
   */
  codeExpiresAt: number | null;
  /** In the order they joined. */
  players: RoomPlayer[];
  /** Players the host removed; they cannot join again with the same id. */
  removed: string[];
  /** 0 in the lobby, then 1, 2, 3… */
  round: number;
  /** How many rounds the game has, when known. */
  rounds: number | null;
  /** When the countdown ends, in ms (host clock). */
  startsAt: number | null;
  /** When the current question closes, in ms (host clock). null: no clock. */
  endsAt: number | null;
  /**
   * What the current round asks, as the host sent it with `question`: whatever
   * the game needs (a prompt and its choices, a number to guess). Every phone
   * and a player who joins late see the same round. null in the lobby.
   * Keep the answer out of it until `reveal`.
   */
  prompt: unknown;
  /** The round's answer, as the host sent it with `reveal`. null until then. */
  solution: unknown;
  /** Total points per player id. */
  scores: Record<string, number>;
  /** This round's answers per player id. Cleared when a new round starts. */
  answers: Record<string, RoomAnswer>;
  /** Points each player won in the last revealed round. */
  lastPoints: Record<string, number>;
  /**
   * Room-wide extras the host shares with every screen, by name: team assignments, breakout
   * groups, pairs (see `team-model`, `breakout-model`, `pair-model`). They ride in the room, so
   * they inherit its guarantees: the newest `seq` wins, a late joiner and a phone that reconnects
   * get them with the state, and a host that restores the room (`restoreRoom`) restores them.
   * Written by the host's `share` event; read with `readShared`, which treats them as untrusted.
   * Absent until the first `share`.
   */
  shared?: Record<string, unknown>;
  /** Bumped on every change, so a client keeps only the newest state. */
  seq: number;
}

export interface RoomAnswer {
  value: unknown;
  /**
   * When it reached the host, in ms (host clock). `useRoom` stamps it on
   * arrival, so a player cannot claim an earlier answer than they gave.
   */
  at: number;
}

export interface RoomSettings {
  /** The most players the room takes. @default 200 */
  maxPlayers?: number;
  /** The longest name, in characters. @default 24 */
  maxNameLength?: number;
}

export function createRoom(init: {
  code: string;
  hostId: string;
  rounds?: number | null;
  /** When the code stops admitting new players, in ms (host clock). */
  codeExpiresAt?: number | null;
}): RoomState {
  return {
    code: init.code,
    hostId: init.hostId,
    phase: 'lobby',
    locked: false,
    codeExpiresAt: init.codeExpiresAt ?? null,
    players: [],
    removed: [],
    round: 0,
    rounds: init.rounds ?? null,
    startsAt: null,
    endsAt: null,
    prompt: null,
    solution: null,
    scores: {},
    answers: {},
    lastPoints: {},
    seq: 0,
  };
}

// --- Events ---------------------------------------------------------------------

/** Events a player sends about themselves. */
export type RoomPlayerEvent =
  | {
      type: 'join';
      playerId: string;
      name: string;
      /**
       * When the join arrived, in ms. `useRoom` stamps it with the host's clock,
       * so an expired code cannot be beaten by a phone with its clock set back;
       * code that calls `applyRoomEvent` directly must stamp it too. While the
       * room has an expiry, an unstamped new join is refused as `expired`.
       */
      at?: number;
    }
  | { type: 'leave'; playerId: string }
  | {
      type: 'answer';
      playerId: string;
      value: unknown;
      /**
       * When the answer arrived. `useRoom` replaces it with the host's clock on
       * receipt; code that calls `applyRoomEvent` directly must do the same
       * rather than trust the sender's value.
       */
      at: number;
    };

/** Events only the host sends. */
export type RoomHostEvent =
  | { type: 'lock'; locked: boolean }
  /** Moves the code's expiry: later to let latecomers in, null for no expiry. */
  | { type: 'extend-code'; expiresAt: number | null }
  | { type: 'remove'; playerId: string }
  /** Starts the countdown to the first round (or the next one). */
  | { type: 'countdown'; startsAt: number }
  /** Opens a round. `endsAt` null for no clock. `prompt`: what the round asks (see `RoomState.prompt`). */
  | { type: 'question'; endsAt: number | null; prompt?: unknown }
  /** Closes the round and adds each player's points. `solution`: the round's answer, for every screen. */
  | { type: 'reveal'; points: Record<string, number>; solution?: unknown }
  | { type: 'podium' }
  | { type: 'close' }
  /** Back to the lobby with the same players, scores at zero and the room open again. */
  | { type: 'restart' }
  /** Sets one named extra for every screen (`RoomState.shared`); `value` null removes it. */
  | { type: 'share'; key: string; value: unknown };

export type RoomEvent = RoomPlayerEvent | RoomHostEvent;

export type RoomRejection =
  | 'not-host'
  | 'not-you'
  | 'closed'
  | 'locked'
  | 'expired'
  | 'full'
  | 'removed'
  | 'name-empty'
  | 'name-taken'
  | 'wrong-phase'
  | 'already-answered'
  | 'unknown-player'
  /** A `share` with a key that is not a short lowercase name, or a value that is not JSON or too big. */
  | 'bad-share';

const HOST_EVENTS = new Set<RoomEvent['type']>([
  'lock',
  'extend-code',
  'remove',
  'countdown',
  'question',
  'reveal',
  'podium',
  'close',
  'restart',
  'share',
]);

/** Names of `shared` entries: lowercase, digits and dashes, so no key can be `__proto__`. */
const SHARE_KEY = /^[a-z][a-z0-9-]{0,31}$/;
/** The most a room's extras may weigh as JSON, in characters: every state message carries them. */
export const MAX_SHARED_SIZE = 60_000;

/** Which phases each host step may follow. */
const NEXT: Partial<Record<RoomEvent['type'], readonly RoomPhase[]>> = {
  countdown: ['lobby', 'reveal'],
  question: ['countdown', 'reveal'],
  reveal: ['question'],
  podium: ['reveal', 'question'],
  restart: ['podium', 'reveal', 'question', 'countdown', 'lobby'],
};

/**
 * True when a join at `at` (host clock) comes after the code stopped admitting new players.
 * Fails closed: when the room has an expiry, a join without `at` counts as expired, so a server
 * that forgets to stamp joins cannot let people in late. Stamp `join.at` with the host clock.
 */
export function codeExpired(state: Pick<RoomState, 'codeExpiresAt'>, at: number | undefined): boolean {
  if (state.codeExpiresAt === null) return false;
  return at === undefined || at >= state.codeExpiresAt;
}

/** A display name, trimmed, inner spaces collapsed, and cut to `max` characters. */
export function cleanName(name: string, max = 24): string {
  return Array.from(name.trim().replace(/\s+/g, ' ')).slice(0, max).join('').trim();
}

const sameName = (a: string, b: string) => a.localeCompare(b, undefined, { sensitivity: 'base' }) === 0;

/**
 * Why `from` may not apply `event` to `state`, or null when they may. The
 * host's own id may send any event; a player may send only their own.
 */
export function rejectRoomEvent(
  state: RoomState,
  event: RoomEvent,
  from: string,
  settings: RoomSettings = {},
): RoomRejection | null {
  const isHost = from === state.hostId;
  if (HOST_EVENTS.has(event.type)) {
    if (!isHost) return 'not-host';
  } else if (!isHost && (event as RoomPlayerEvent).playerId !== from) {
    return 'not-you';
  }
  if (state.phase === 'closed') return 'closed';

  const allowed = NEXT[event.type];
  if (allowed && !allowed.includes(state.phase)) return 'wrong-phase';

  switch (event.type) {
    case 'join': {
      if (state.removed.includes(event.playerId)) return 'removed';
      const name = cleanName(event.name, settings.maxNameLength);
      if (!name) return 'name-empty';
      const known = state.players.find((p) => p.id === event.playerId);
      if (state.players.some((p) => p.id !== event.playerId && sameName(p.name, name))) return 'name-taken';
      if (known) return null; // a reconnect, even when locked
      if (state.locked) return 'locked';
      if (codeExpired(state, event.at)) return 'expired';
      if (state.players.length >= (settings.maxPlayers ?? 200)) return 'full';
      return null;
    }
    case 'leave':
      return state.players.some((p) => p.id === event.playerId) ? null : 'unknown-player';
    case 'answer':
      if (state.phase !== 'question') return 'wrong-phase';
      if (!state.players.some((p) => p.id === event.playerId)) return 'unknown-player';
      if (event.playerId in state.answers) return 'already-answered';
      return null;
    case 'remove':
      return state.players.some((p) => p.id === event.playerId) ? null : 'unknown-player';
    case 'share': {
      if (!SHARE_KEY.test(event.key)) return 'bad-share';
      const json = JSON.stringify(event.value);
      return json === undefined || json.length > MAX_SHARED_SIZE ? 'bad-share' : null;
    }
    default:
      return null;
  }
}

/**
 * The room after `event` from `from`. Returns the same object when the
 * event is refused (see `rejectRoomEvent`), so `next === state` means
 * nothing happened.
 */
export function applyRoomEvent(
  state: RoomState,
  event: RoomEvent,
  from: string,
  settings: RoomSettings = {},
): RoomState {
  if (rejectRoomEvent(state, event, from, settings)) return state;
  const next = (patch: Partial<RoomState>): RoomState => ({
    ...state,
    ...patch,
    seq: state.seq + 1,
  });

  switch (event.type) {
    case 'join': {
      const name = cleanName(event.name, settings.maxNameLength);
      const known = state.players.some((p) => p.id === event.playerId);
      return next({
        players: known
          ? state.players.map((p) => (p.id === event.playerId ? { ...p, name, connected: true } : p))
          : [...state.players, { id: event.playerId, name, connected: true }],
        scores: known ? state.scores : { ...state.scores, [event.playerId]: 0 },
      });
    }
    case 'leave':
      return next({
        players: state.players.map((p) => (p.id === event.playerId ? { ...p, connected: false } : p)),
      });
    case 'answer':
      return next({
        answers: {
          ...state.answers,
          [event.playerId]: { value: event.value, at: event.at },
        },
      });
    case 'lock':
      return next({ locked: event.locked });
    case 'extend-code':
      return next({ codeExpiresAt: event.expiresAt });
    case 'remove': {
      const { [event.playerId]: _score, ...scores } = state.scores;
      const { [event.playerId]: _answer, ...answers } = state.answers;
      return next({
        players: state.players.filter((p) => p.id !== event.playerId),
        removed: [...state.removed, event.playerId],
        scores,
        answers,
      });
    }
    case 'countdown':
      return next({
        phase: 'countdown',
        startsAt: event.startsAt,
        endsAt: null,
      });
    case 'question':
      return next({
        phase: 'question',
        round: state.round + 1,
        endsAt: event.endsAt,
        prompt: event.prompt ?? null,
        solution: null,
        answers: {},
        lastPoints: {},
      });
    case 'reveal': {
      const scores = { ...state.scores };
      const lastPoints: Record<string, number> = {};
      for (const p of state.players) {
        const won = Number.isFinite(event.points[p.id]) ? event.points[p.id]! : 0;
        lastPoints[p.id] = won;
        scores[p.id] = (scores[p.id] ?? 0) + won;
      }
      return next({ phase: 'reveal', scores, lastPoints, endsAt: null, solution: event.solution ?? null });
    }
    case 'podium':
      return next({ phase: 'podium', endsAt: null });
    case 'close':
      return next({
        phase: 'closed',
        locked: true,
        startsAt: null,
        endsAt: null,
      });
    case 'share': {
      const { [event.key]: _old, ...rest } = state.shared ?? {};
      return next({ shared: event.value === null ? rest : { ...rest, [event.key]: event.value } });
    }
    case 'restart':
      return next({
        phase: 'lobby',
        locked: false,
        round: 0,
        startsAt: null,
        endsAt: null,
        prompt: null,
        solution: null,
        answers: {},
        lastPoints: {},
        scores: Object.fromEntries(state.players.map((p) => [p.id, 0])),
      });
  }
}

// --- Guessing codes -------------------------------------------------------------

/*
 * Stops people guessing their way into a room. Every wrong code counts
 * against where it came from (a network, a device, whatever key your server
 * trusts) and against the room as a whole; past either limit, more tries are
 * refused until the window moves on. A six-character code from
 * `makeJoinCode` has about 600 million values, so five tries per source and
 * thirty per room leave a guesser nowhere, while a person who mistyped twice
 * is never stopped. Pure and serialisable: keep the state wherever the code
 * is checked (a server, an edge function, the host), call `checkJoinAttempt`
 * before comparing the code and `recordJoinAttempt` after.
 */

export interface JoinGuardOptions {
  /** Wrong tries one source may make in the window. @default 5 */
  perSource?: number;
  /** Wrong tries the whole room accepts in the window, across sources. @default 30 */
  total?: number;
  /** How far back wrong tries count, in ms. @default 10 minutes */
  windowMs?: number;
}

export interface JoinGuardState {
  /** Wrong tries, oldest first. */
  failures: { source: string; at: number }[];
}

export type JoinGuardVerdict =
  | { allowed: true; left: number }
  | {
      allowed: false;
      /** `source`: this source used its tries. `room`: the room stopped taking guesses. */
      reason: 'source' | 'room';
      /** When the oldest counted try leaves the window and one more is allowed, in ms. */
      retryAt: number;
    };

const DEFAULTS = { perSource: 5, total: 30, windowMs: 10 * 60_000 };

const settings = (o: JoinGuardOptions) => ({
  perSource: Math.max(1, Math.floor(o.perSource ?? DEFAULTS.perSource)),
  total: Math.max(1, Math.floor(o.total ?? DEFAULTS.total)),
  windowMs: Math.max(1, o.windowMs ?? DEFAULTS.windowMs),
});

export function createJoinGuard(): JoinGuardState {
  return { failures: [] };
}

/** Drops wrong tries older than the window. */
export function pruneJoinGuard(state: JoinGuardState, now: number, options: JoinGuardOptions = {}): JoinGuardState {
  const { windowMs } = settings(options);
  const failures = state.failures.filter((f) => now - f.at < windowMs);
  return failures.length === state.failures.length ? state : { failures };
}

/** May `source` try a code now? Ask before comparing the code, so a blocked source learns nothing. */
export function checkJoinAttempt(
  state: JoinGuardState,
  source: string,
  now: number,
  options: JoinGuardOptions = {},
): JoinGuardVerdict {
  const { perSource, total, windowMs } = settings(options);
  const recent = pruneJoinGuard(state, now, options).failures;
  const mine = recent.filter((f) => f.source === source);
  if (recent.length >= total) {
    return { allowed: false, reason: 'room', retryAt: recent[recent.length - total]!.at + windowMs };
  }
  if (mine.length >= perSource) {
    return { allowed: false, reason: 'source', retryAt: mine[mine.length - perSource]!.at + windowMs };
  }
  return { allowed: true, left: Math.min(perSource - mine.length, total - recent.length) };
}

/** The guard after a try: a wrong code is counted, a right one changes nothing. */
export function recordJoinAttempt(
  state: JoinGuardState,
  source: string,
  correct: boolean,
  now: number,
  options: JoinGuardOptions = {},
): JoinGuardState {
  const pruned = pruneJoinGuard(state, now, options);
  return correct ? pruned : { failures: [...pruned.failures, { source, at: now }] };
}

// --- Reading the state ----------------------------------------------------------

/**
 * How far the host's clock is ahead of this one, in ms, from `{ at, local }` pairs: the host's
 * send time and this client's receive time. A message can only arrive after it was sent, so each
 * `at - local` is a lower bound on the true offset and the largest is the closest. Pass the recent
 * samples only, so a host whose clock is reset is followed. 0 with no samples.
 */
export function clockOffset(samples: readonly { at: number; local: number }[]): number {
  let best = -Infinity;
  for (const s of samples) if (Number.isFinite(s.at) && Number.isFinite(s.local)) best = Math.max(best, s.at - s.local);
  return best === -Infinity ? 0 : best;
}

/** Players still connected. */
export function connectedPlayers(state: RoomState): RoomPlayer[] {
  return state.players.filter((p) => p.connected);
}

/** How many connected players have answered this round, of how many. */
export function answerProgress(state: RoomState): {
  answered: number;
  total: number;
} {
  const live = connectedPlayers(state);
  return {
    answered: live.filter((p) => p.id in state.answers).length,
    total: live.length,
  };
}

/** Everyone in the room by score, ties sharing a rank (the leaderboard's ranking). */
export function roomStandings(state: RoomState): RankedEntry[] {
  return rankEntries(
    state.players.map((p) => ({
      id: p.id,
      name: p.name,
      score: state.scores[p.id] ?? 0,
    })),
  );
}

/**
 * One named extra from `RoomState.shared`, read as untrusted: `decode` gets whatever is there
 * (anything, from an older version of the app or a bad client) and returns the value or null.
 * Null too when it is absent, or when `decode` throws, so a screen shows "nothing set" rather
 * than breaking.
 */
export function readShared<T>(
  state: Pick<RoomState, 'shared'> | null | undefined,
  key: string,
  decode: (raw: unknown) => T | null,
): T | null {
  const shared = state?.shared;
  if (!shared || !Object.hasOwn(shared, key)) return null;
  try {
    return decode(shared[key]);
  } catch {
    return null;
  }
}

// --- Keeping a room across a refresh -------------------------------------------------

/**
 * How far `restoreRoom` moves `seq` ahead. A host that restores a save written just before its
 * last few changes would otherwise send states the phones already hold newer ones of, and every
 * phone would ignore them.
 */
export const RESTORE_SEQ_JUMP = 1_000;

const PHASES: readonly RoomPhase[] = ['lobby', 'countdown', 'question', 'reveal', 'podium', 'closed'];

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
const isNum = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);
const nullableNum = (v: unknown): number | null | undefined => (v === null ? null : isNum(v) ? v : undefined);
const isCount = (v: unknown): v is number => isNum(v) && Number.isInteger(v) && v >= 0;

/** A record read from JSON, as plain own properties (a `__proto__` key stays data), values checked. */
function cleanRecord<T>(raw: unknown, ok: (v: unknown) => T | undefined): Record<string, T> {
  const out: [string, T][] = [];
  if (isRecord(raw)) {
    for (const [k, v] of Object.entries(raw)) {
      const value = ok(v);
      if (value !== undefined) out.push([k, value]);
    }
  }
  return Object.fromEntries(out);
}

/** The room as text, to keep in `localStorage` or on a server, so a host that refreshes can go on. */
export function serializeRoom(state: RoomState): string {
  return JSON.stringify(state);
}

/**
 * The room from text written by `serializeRoom`, or null when it is not one (absent, damaged, from
 * another host). Everything is checked and rebuilt, never trusted. Nobody is known to be here yet:
 * each player comes back `away`, and a phone that is still open says so by itself (it sees itself
 * away and joins again), so the host never shows someone present who left while it was down.
 * Scores, answers, rounds, clocks and the room's extras are kept, and `seq` moves ahead by
 * `RESTORE_SEQ_JUMP` so phones take the restored state as the newest.
 *
 * Pass `hostId` to refuse a room saved by someone else.
 */
export function restoreRoom(text: string | null | undefined, options: { hostId?: string } = {}): RoomState | null {
  if (!text) return null;
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    return null;
  }
  if (!isRecord(raw)) return null;
  const { code, hostId, phase, players, seq, round } = raw;
  if (typeof code !== 'string' || !code || typeof hostId !== 'string' || !hostId) return null;
  if (options.hostId !== undefined && hostId !== options.hostId) return null;
  if (!PHASES.includes(phase as RoomPhase) || !Array.isArray(players) || !isCount(seq) || !isCount(round)) return null;
  const seen = new Set<string>();
  const kept: RoomPlayer[] = [];
  for (const p of players) {
    if (!isRecord(p) || typeof p.id !== 'string' || typeof p.name !== 'string') return null;
    if (seen.has(p.id)) continue;
    seen.add(p.id);
    kept.push({ id: p.id, name: p.name, connected: false });
  }
  const rounds = raw.rounds === null || raw.rounds === undefined ? null : isCount(raw.rounds) ? raw.rounds : undefined;
  const startsAt = nullableNum(raw.startsAt ?? null);
  const endsAt = nullableNum(raw.endsAt ?? null);
  const codeExpiresAt = nullableNum(raw.codeExpiresAt ?? null);
  if (rounds === undefined || startsAt === undefined || endsAt === undefined || codeExpiresAt === undefined) return null;
  const num = (v: unknown) => (isNum(v) ? v : undefined);
  const answer = (v: unknown) => (isRecord(v) && isNum(v.at) ? { value: v.value, at: v.at } : undefined);
  const state: RoomState = {
    code,
    hostId,
    phase: phase as RoomPhase,
    locked: raw.locked === true,
    codeExpiresAt,
    players: kept,
    removed: Array.isArray(raw.removed) ? raw.removed.filter((id): id is string => typeof id === 'string') : [],
    round,
    rounds,
    startsAt,
    endsAt,
    prompt: raw.prompt ?? null,
    solution: raw.solution ?? null,
    scores: cleanRecord(raw.scores, num),
    answers: cleanRecord(raw.answers, answer),
    lastPoints: cleanRecord(raw.lastPoints, num),
    seq: seq + RESTORE_SEQ_JUMP,
  };
  if (isRecord(raw.shared)) state.shared = Object.fromEntries(Object.entries(raw.shared).filter(([k]) => SHARE_KEY.test(k)));
  return state;
}

/** Where a host keeps its room between page loads. `Storage` fits (`localStorage`, `sessionStorage`). */
export interface RoomStorage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

/**
 * A room kept in `storage` under `key`. Storage that is missing, full or blocked (a private window,
 * a storage-less embed) never throws: `load` finds nothing and `save` does nothing, and the room
 * carries on in memory. Call `save` after every change, `clear` when the game ends.
 */
export function createRoomStore(
  storage: RoomStorage | null | undefined,
  key: string,
  options: { hostId?: string } = {},
): { load(): RoomState | null; save(state: RoomState): void; clear(): void } {
  return {
    load() {
      try {
        return restoreRoom(storage?.getItem(key), options);
      } catch {
        return null;
      }
    },
    save(state) {
      try {
        storage?.setItem(key, serializeRoom(state));
      } catch {
        /* a full or blocked store must not stop the game */
      }
    },
    clear() {
      try {
        storage?.removeItem(key);
      } catch {
        /* nothing to clear */
      }
    },
  };
}

// --- Transport ------------------------------------------------------------------

/** What travels between the host and the players. */
export type RoomMessage =
  /** A player asks the host to apply an event. */
  | { kind: 'intent'; from: string; event: RoomEvent }
  /** The host's room, after every change. */
  | {
      kind: 'state';
      state: RoomState;
      /** The host's clock when it sent this, in ms. Phones use it to read deadlines on the host's time. */
      at?: number;
    }
  /** A client that just arrived asks for the current state. */
  | { kind: 'hello'; from: string }
  /** The host refused a player's intent, and why. */
  | {
      kind: 'rejected';
      to: string;
      event: RoomEvent['type'];
      reason: RoomRejection;
    };

/**
 * How a room talks. `send` reaches every other client in the room (not the
 * sender); `subscribe` returns an unsubscribe. Wrap any realtime service in
 * these two functions.
 */
export interface RoomTransport<M = RoomMessage> {
  send(message: M): void;
  subscribe(listener: (message: M) => void): () => void;
  /** Optional: release the connection. */
  close?(): void;
}

/**
 * An in-memory room: every `connect()` is a client, and messages arrive on
 * the next microtask, like a network would deliver them. For tests, demos
 * and a host and players on one screen.
 */
export function createMemoryRoomHub<M = RoomMessage>(): { connect(): RoomTransport<M> } {
  const clients = new Set<(message: M) => void>();
  return {
    connect() {
      const own = new Set<(message: M) => void>();
      const deliver = (message: M) => own.forEach((l) => l(message));
      clients.add(deliver);
      return {
        send(message) {
          const copy = JSON.parse(JSON.stringify(message)) as M;
          queueMicrotask(() => clients.forEach((c) => c !== deliver && c(copy)));
        },
        subscribe(listener) {
          own.add(listener);
          return () => own.delete(listener);
        },
        close() {
          clients.delete(deliver);
          own.clear();
        },
      };
    },
  };
}

/**
 * A transport over `BroadcastChannel`: every tab of the same site on this
 * device that opens the same `name` is in the room. Null where the browser
 * has no BroadcastChannel.
 */
export function createBroadcastRoomTransport<M = RoomMessage>(name: string): RoomTransport<M> | null {
  if (typeof BroadcastChannel === 'undefined') return null;
  const channel = new BroadcastChannel(name);
  return {
    send: (message) => channel.postMessage(message),
    subscribe(listener) {
      const handle = (e: MessageEvent<M>) => listener(e.data);
      channel.addEventListener('message', handle);
      return () => channel.removeEventListener('message', handle);
    },
    close: () => channel.close(),
  };
}
